save('95F2C4','0,5',[
 ('Выбрать модель трёх независимых бросков симметричной монеты','Восемь равновозможных последовательностей. Событие: ни одного или ровно одно начало с мячом.',['bernoulli'],['condition']),
 ('Посчитать благоприятные последовательности и вероятность','Для нуля успехов 1 исход, для одного C(3,1)=3. P=(1+3)/8=1/2.',['count','prob'],['s1'])],
 [('bernoulli','Моделировать независимые испытания с двумя исходами','Задать последовательность независимых испытаний с фиксированной вероятностью успеха; независимость и симметрия жеребьёвки являются условиями модели.'),
 ('count','Считать размещения заданного числа успехов','Выбрать позиции k успехов среди n испытаний числом сочетаний C(n,k).'),
 ('prob','Вычислять вероятность по числу равновозможных исходов','Разделить число благоприятных исходов на общее число в конечном пространстве равновозможных исходов.')],
 [('Подсчитать последовательности с нулём или одним успехом',[1,2])],warnings=['Используется обычная для задачи модель независимой честной жеребьёвки; явной вероятности в условии нет.'])

save('7B10F3','а) нет; б) нет; в) 11',[
 ('Вывести ограничение на число k чисел с последней цифрой 6','По последним цифрам 2(30-k)+6k≡2454 (mod 10), то есть 4k≡4 (mod 10), k≡1 (mod 5). Возможны 1,6,11,16,21,26.',['mod'],['condition']),
 ('а) Проверить равное число двух типов','При k=15 нарушается k≡1 (mod 5). Поровну быть не может.',['mod'],['s1']),
 ('б) Оценить минимальную сумму при k=1','29 различных чисел вида 10j+2 имеют сумму не меньше 2+12+...+282=4118. Добавление минимум 6 даёт 4124>2454. Ответ нет.',['min','series'],['condition','s1']),
 ('в) Проверить следующий допустимый меньший k=6','24 числа с последней цифрой 2 дают минимум 2808, шесть с последней цифрой 6 — 186. Итого 2994>2454; k=6 невозможен. Все k<11 исключены.',['min','series'],['s1']),
 ('в) Предъявить набор при k=11','Взять 19 чисел 2,12,...,182 и 11 чисел 6,16,...,106: сумма 1748+616=2364. Заменить 182 на 272: сумма станет 2454, последняя цифра и различность сохранены. Минимум 11.',['construct','series'],['s1','s3','s4'])],
 [('mod','Применять сравнения по модулю к сумме целых чисел','Связать допустимые остатки с количеством слагаемых и получить необходимое ограничение по модулю.'),
 ('min','Оценивать сумму различных чисел заданных классов снизу','Для каждого непересекающегося класса остатков взять минимальные различные положительные представители и сложить нижние оценки.'),
 ('series','Суммировать арифметическую прогрессию','По числу членов и крайним членам вычислить сумму арифметической прогрессии; отдельные исключённые/добавленные члены учитывать явно.'),
 ('construct','Строить целочисленный пример с заданными ограничениями','Выбрать числа, удовлетворяющие количеству, остаткам, различности и сумме, и проверить каждое ограничение.')],
 [('а) Использовать последние цифры',[1,2]),('б) Оценить сумму снизу',[3]),('в) Исключить меньшие допустимые количества и построить пример',[1,4,5])])

save('65E80F','4 км/ч',[
 ('Составить уравнение времени движения с течением и против течения','При скорости течения c имеем 0≤c<22; время движения 47-3=44 ч. Поэтому 468/(22+c)+468/(22-c)=44.',['motion'],['condition']),
 ('Устранить знаменатели на допустимой области','468·44/(484-c²)=44, откуда 484-c²=468 и c²=16. Знаменатель положителен при c<22.',['rational'],['s1']),
 ('Найти корни и отобрать физически допустимый','c=±4; условию 0≤c<22 отвечает c=4. Проверка: 468/26+468/18+3=18+26+3=47 ч.',['square','filter'],['s1','s2'])],
 [('motion','Составлять уравнение времени при движении по течению','Использовать скорости v±c и время s/v, отделить стоянку и сохранить положительность скоростей.'),
 ('rational','Преобразовывать рациональное уравнение с учётом знаменателей','Установить ненулевые знаменатели и умножить уравнение на общий знаменатель без добавления запрещённых корней.'),
 ('square','Решать уравнение вида x²=c','Для c≥0 найти оба действительных квадратных корня; при c<0 действительных корней нет.'),
 ('filter','Отбирать алгебраические решения по условиям модели','Проверить корни на физический смысл, область допустимых значений и исходное соотношение.')],
 [('Составить баланс времени рейса и решить рациональное уравнение',[1,2,3])])

save('F2A2EB','а) углы равны; б) S(AEM):S(CMK)=4:9',[
 ('а) Использовать свойство серединного перпендикуляра','EB=EM и KB=KM. Пусть β=∠ABM,γ=∠MBC; β+γ=60°.',['bisector'],['condition']),
 ('а) Выразить углы через β и γ','В равнобедренном BEM углы при B,M равны β, поэтому ∠AEM=2β. В BKM углы при B,M равны γ; ∠CMB=120°-γ, значит ∠CMK=120°-2γ=2β. Равенство доказано.',['iso','angles'],['condition','s1']),
 ('Установить подобие треугольников с правильным соответствием','∠EAM=∠MCK=60° и ∠AEM=∠CMK. Поэтому AEM~CMK, соответствие A↔C,E↔M,M↔K; коэффициент равен AE/CM.',['similar'],['condition','s2']),
 ('б) Найти AE по равенству EB=EM и теореме косинусов','Масштабируем AC=AB=5,AM=1,CM=4. При AE=e получаем EM²=e²-e+1 и EB=5-e. Тогда (5-e)²=e²-e+1 ⇒ e=8/3.',['cos','lin'],['condition','s1']),
 ('б) Перейти от коэффициента подобия к отношению площадей','AE/CM=(8/3)/4=2/3, поэтому S(AEM)/S(CMK)=(2/3)²=4/9. Отношение AM/CM само по себе не является коэффициентом этих соответствующих сторон.',['area'],['s3','s4'])],
 [('bisector','Использовать геометрическое место равноудалённых точек','Точка серединного перпендикуляра к отрезку равноудалена от его концов.'),
 ('iso','Выражать углы равнобедренного треугольника','Из равенства сторон получить равенство противолежащих углов и выразить угол при вершине.'),
 ('angles','Находить углы через сумму и смежность','Использовать сумму углов треугольника и смежность при известных положениях лучей; сохранять геометрические основания.'),
 ('similar','Доказывать подобие по двум углам','Установить две пары равных углов и явно определить соответствие вершин и сторон.'),
 ('cos','Применять теорему косинусов','Связать три стороны и косинус угла между двумя из них в невырожденном треугольнике.'),
 ('lin','Решать линейное уравнение с числовыми коэффициентами','Преобразовать аффинное равенство одной переменной и получить его множество решений; переносы и деление входят в одно действие.'),
 ('area','Находить отношение площадей подобных фигур','Возвести коэффициент подобия соответствующих длин в квадрат; не подставлять отношение несоответствующих сторон.')],
 [('Доказать подобие, вычислить соответствующую сторону и отношение площадей',[1,2,3,4,5])])

save('c15c1c','24000 км/ч²',[
 ('Подставить данные в формулу скорости и установить допустимость','120=√(2·0,3·a)=√(0,6a), поэтому a≥0.',['formula'],['condition']),
 ('Решить уравнение с квадратным корнем','Обе стороны неотрицательны, поэтому возведение в квадрат равносильно: 14400=0,6a ⇒ a=24000. Проверка: √14400=120, единицы км/ч².',['radical','lin'],['s1'])],
 [('formula','Подставлять величины в заданную формулу','Соотнести данные с обозначениями, согласовать единицы и сохранить допустимые значения переменных.'),
 ('radical','Снимать квадратный корень равносильным возведением в квадрат','Установить неотрицательность обеих сторон равенства и перейти к квадратам; без знаковых условий преобразование может добавить корни.'),
 ('lin','Решать линейное уравнение с числовыми коэффициентами','Преобразовать аффинное равенство одной переменной и получить его множество решений; переносы и деление входят в одно действие.')],
 [('Подставить данные и снять квадратный корень',[1,2])])

save('C83C8C','0,125',[
 ('Выразить нужную последовательность исходов жеребьёвки','Нужно проиграть первую жеребьёвку, выиграть вторую и проиграть третью; вероятности каждого нужного исхода 1/2.',['bernoulli'],['condition']),
 ('Перемножить вероятности независимых событий','P=(1/2)³=1/8=0,125. Число сочетаний не нужно: позиции успехов уже заданы.',['product'],['s1'])],
 [('bernoulli','Моделировать независимые испытания с двумя исходами','Задать последовательность независимых испытаний с фиксированной вероятностью успеха; независимость и симметрия жеребьёвки являются условиями модели.'),
 ('product','Вычислять вероятность пересечения независимых событий','При обоснованной независимости перемножить вероятности событий, которые должны произойти одновременно.')],
 [('Вычислить вероятность фиксированной последовательности жеребьёвок',[1,2])],warnings=['Используется стандартная модель независимого равновероятного жребия.'])

save('142CDC','а) SA∥α; б) arccos(11/20)',[
 ('Ввести координаты правильной пирамиды и найти её высоту','A=(0,0,0),B=(6,0,0),C=(6,6,0),D=(0,6,0),S=(3,3,h). По SA²=18+h²=49 имеем h=√31.',['coords','pyth'],['condition']),
 ('Найти координаты точек деления рёбер','DN:NC=1:2 ⇒ N=(2,6,0); SK:KC=1:2 ⇒ K=(4,4,2h/3).',['division'],['condition','s1']),
 ('Построить нормаль плоскости α по двум направлениям','Направления BC=(0,1,0) и NK=(2,-2,2h/3) лежат в α. Нормаль nα=(h,0,-3), уравнение h(x-2)-3z=0.',['normal'],['condition','s2']),
 ('а) Проверить параллельность SA и α','Направление SA=(-3,-3,-h) ортогонально nα: -3h+3h=0. Точка A не лежит в α, поскольку -2h≠0; следовательно SA параллельна α и не содержится в ней.',['parallel'],['s1','s3']),
 ('б) Найти нормаль грани SBC и угол между плоскостями','Для SBC подходит n=(h,0,3). cos φ=|nα·n|/(|nα||n|)=|h²-9|/(h²+9)=22/40=11/20. Меньший угол φ=arccos(11/20).',['normal','planeangle'],['s1','s3'])],
 [('coords','Задавать пространственную фигуру декартовыми координатами','Выбрать систему координат, воспроизводящую заданные длины, симметрию и взаимное расположение элементов.'),
 ('pyth','Находить длину по теореме Пифагора','Для установленного прямоугольного треугольника использовать сумму квадратов катетов и учесть положительность длины.'),
 ('division','Находить координаты точки деления отрезка','Выразить точку как аффинную комбинацию концов в заданном внутреннем отношении.'),
 ('normal','Находить нормаль плоскости по направлениям','Найти ненулевой вектор, ортогональный двум непараллельным направлениям плоскости, и составить её уравнение по точке.'),
 ('parallel','Проверять параллельность прямой и плоскости по нормали','Проверить нулевое скалярное произведение направления прямой с нормалью и отдельно исключить принадлежность прямой плоскости.'),
 ('planeangle','Вычислять угол между плоскостями по нормалям','Использовать модуль скалярного произведения нормалей, делённый на произведение длин, для меньшего угла между плоскостями.')],
 [('Ввести координаты и использовать нормали плоскостей',[1,2,3,4,5])])

save('073F98',r'a∈(0;6)\{2;4}',[
 ('Разделить уравнение по знаку x','При x≥0: 2x²+(a-12)x+a(6-a)=0. При x<0: 2x²+(a+6)x+a(6-a)=0. Нулевой корень возможен лишь при a=0 или 6.',['abs'],['condition']),
 ('Разложить квадратные уравнения на множители','В первой ветви корни x=a/2 и x=6-a; во второй x=-a и x=a/2-3. Это следует из 2(x-a/2)(x+a-6) и 2(x+a)(x-a/2+3).',['factorparam'],['s1']),
 ('Потребовать по два допустимых корня в каждой ветви','Для четырёх различных корней нуль исключён, иначе объединение ветвей имеет не более трёх корней. Два положительных и два отрицательных корня требуют 0<a<6.',['count'],['s1','s2']),
 ('Исключить совпадения внутри ветвей и проверить достаточность','a/2=6-a только при a=4; -a=a/2-3 только при a=2. Положительные и отрицательные корни между собой не совпадут. Ответ (0;6) без 2 и 4.',['count','sets'],['s2','s3'])],
 [('abs','Раскрывать модуль разбиением области по знаку','Заменить |x| выражениями x и -x на соответствующих полуосях, явно распределив граничную точку.'),
 ('factorparam','Факторизовать квадратный трёхчлен с параметром','Найти множители параметрического квадратного трёхчлена и проверить тождество раскрытием скобок.'),
 ('count','Считать различные корни с учётом ветвей и границ','Проверить принадлежность каждого кандидата своей области, исключить совпадения и правильно учесть общий граничный корень.'),
 ('sets','Пересекать множества допустимых значений','Совместить несколько необходимых ограничений и правильно включить или исключить граничные точки.')],
 [('Разбить по знаку, факторизовать ветви и посчитать допустимые корни',[1,2,3,4])])
